const LISTENERS = new Set();
export function captureServerFunctionCall(listener) {
    LISTENERS.add(listener);
    return () => LISTENERS.delete(listener);
}
export function pushRequest(id, instance, source) {
    const event = {
        type: "request",
        id,
        instance,
        source,
        time: performance.now(),
    };
    for (const listener of new Set(LISTENERS)) {
        listener(event);
    }
}
export function pushResponse(id, instance, source) {
    const event = {
        type: "response",
        id,
        instance,
        source,
        time: performance.now(),
    };
    for (const listener of new Set(LISTENERS)) {
        listener(event);
    }
}
